import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"同人","description":"高岛易断 - 同人","frontmatter":{"title":"同人","description":"高岛易断 - 同人"},"headers":[],"relativePath":"zh/classics/takashima/013.md","filePath":"zh/classics/takashima/013.md"}'),i={name:"zh/classics/takashima/013.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="同人" tabindex="-1">同人 <a class="header-anchor" href="#同人" aria-label="Permalink to “同人”">​</a></h1><h2 id="同人-1" tabindex="-1">同人 <a class="header-anchor" href="#同人-1" aria-label="Permalink to “同人”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>同人：同人于野，亨，利涉大川，利君子贞。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《同人》之道，要在广远无间，中外如一，斯谓之大同。“野”谓旷野，取远与外之义；“于野，”则上天下地，空阔无际，无所容其私心，斯物无不应，人无不助，故“亨”。心无私欲，则地无险阻，无往不利，虽大川亦可涉。但同亦分公私，合我者同，不合者异，是小人之党也，非同也；要必公正无私，浑然天心，虽千里之遥，干载之后，志无不合，道无不同，故曰“利君子贞”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>天与火，同人，君子以类族辨物。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>此卦《乾》上《离》下，《象传》不曰火在天下，而曰“天与火”，盖以《乾》为日，《离》亦为日，象相同也，故曰“天与火”，取其同也。《乾》阳上升，《离》火上炎，性相同也，犹人生性无不相同，故曰《同人》。君子法乾之健，以类其族，用离之明，以辨其物；于异中求同，故族必类之，于同中求共，故物必辨之。凡异之不可不明辨，益知同之不容以相混也。即此而推之，知人有善恶邪正之分，心有是非公私之判，君子亦必当类而观之，辨而别之。如周之与比，党之与群，其貌若相似，其心则自别。要必明析严辨，不稍假借，是异其所不得不共，乃能同其所不得不同。此所以为同之大者也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：目下大有升腾之象，且得朋友扶助，大吉。</p><p>○　问商业：宜于合资会社等业，大利。</p><p>○　问家宅：得合家和悦之象，吉。</p><p>○　问战征：主军士同心，即宜调兵进攻，大利。</p><p>○　问疾病：是火症也，恐医药有误，宜别求良医。</p><p>○　问讼事：防有同党私庇，一时未可结案。</p><p>○　问六甲：生女。</p><p>○　问失物：须细细于物类中寻觅，乃得。</p><p>○　问行人：即日可归，必与友偕来。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初九居一卦之始，为《同人》之首也。此卦以二爻为主。初变阴下卦为艮，象门，故曰“于门”，亦不愿独同于二，故欲出门以广交也。门以外无所私昵，故“无咎”。《象传》则颠倒其辞曰，“出门同人”，显言一出门外，天地万物，孰不吾同？不曰无咎，而曰“又谁咎也”，盖无咎，第属己言，“又谁咎”，则见门外之人，皆乐与之同，谁复得咎之者？《易》以人名卦者，《家人》《同人》两卦。《家人》者，一家之人，宜位正夫内；《同人》者，天下之人也，宜志通夫外。《易》言“出门”者，《随》与《同人》两卦，《随》曰出门有功，《同人》曰出门无咎，皆以门内为易溺于私，门外则廓然大公矣。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：目下平顺，宜经营出外，利。</p><p>○　问家宅：一门之内，雍雍和睦，无咎。</p><p>○　问商业：利行商，不利坐贾。</p><p>○　问疾病：宜避地调养，无碍。</p><p>○　问讼事：防有惩役之患，宜预出躲避，可以免咎。</p><p>○　问失物：须于门外寻觅。</p><p>○　问六甲：即时可产，得男。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>一日友人某氏来请占气运，筮得《同人》之《遁》。</p><p>断曰：此卦为出门求友之象也。交际之道，宜与善人同，不宜与不善人同。爻辞曰“于门”，《象传》曰“出门”，言出外自得《同人》之助。盖在内则相与者皆亲好，不能无私，私则有咎；出门则往来者皆同与，故无咎也。今占得《同人》初爻，知君必初次出门者也。君可放胆做去，他日必得高位，博众望，可预决也。某用之，后果大得人望，如占所云。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>此爻以阴居阴，文明中正，而为全卦之主，卦中诸阳，皆求应二。二与九五为正应，九五为君，居一卦之尊位，二爻曰“同人于宗”，“宗”尊也，言二得同于至尊。在二与五，刚柔中正，时位相应，可谓尽善，但两相亲密，未免偏私，有失至公大同之量。且三四两爻，求同不得，见二与五，同意亲密，致生嫉妒，即所以取吝也，故曰“同人于宗，吝”。《象传》曰“吝道也”，道字最宜玩味，谓一时即未见吝，而已有取吝之道也。《彖》辞以六二得位得中，曰“亨”，爻义以“同人于宗”，曰“吝”，盖卦体主大同，爻义戒阿党也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：目下未佳，虽有相助，而相忌者多，未能百事遂意。</p><p>○　问商业：利于大宗买卖，惟须出纳宜留意。得利。</p><p>○　问讼事：不利。</p><p>○　问家宅：以勤俭起家，得长子之力。</p><p>○　问疾病：有魂归宗庙之象，凶。</p><p>○　问行人：即返。</p><p>○　问六甲：生女。</p><p>○　问失物：被拾者藏匿，不见还也。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治三年，占自气运，与将来之方向如何。</p><p>我国维新之初，明治元年，有奥羽北越之役，二年有箱馆之征讨，天下之形势未宁。三年干戈既息，天下拭目，以望升平。当是时余大有所感，自以生长商家，惟汲汲谋兴家业，未逞计及国事，兹幸遭遇圣代，得与贵显诸公，朝夕面晤，深荷款遇。在诸公毁家纾难，勤劳王事，皆维新之功臣也，如余者得生长今日，际盛运，而于国家毫无建树，实可耻之甚也。兹愿稍展寸长，勉力从公，冀图深厚之报，为此自占现时气运，与进步之方向。筮得《同人》。断曰：幕府末路，升平日久，政纲废弛，加以外交事起，当时君子不得其位，小人得逞其奸，上下闭塞，秩序紊乱。于是豪杰之士，所在兴起，天下翕然应之，拔乱反正，一变否极之世，得启今日泰平之盛，是即《同人》之卦也。今筮得此卦，《彖传》曰，“同人，柔得位得中而应乎乾，曰《同人》”。以六二一柔得位中正，应上卦九五之中正，是余居民间中正之地位，上与政府之政略相应，同其目的，“柔”者，谓余本无爵位，才力柔弱。曰“同人于野”，谓余本是在野草莽之臣也。“亨”者，谓余之气运与天下之大势，悉当亨通，凡为国家创兴事业，无不成功也。按《同人》一卦，卦体则主大同，爻义则戒偏私，独“于野”曰亨，盖宜远取于外，不宜近取于内也。且《彖传》曰“乾行”，“乾行”者，自强也；曰“利涉大川”，“利涉”者，兴造舟揖也；曰“文明以健”，“文明”者，创修文学也。卦象所言，皆一一示余着手之方向，且教余取法海外之造作，通行于天下，故曰“为能通天下之志”。余既得此卦象，惟冀有辅政府剧务万一，区区家资，遑足惜乎！明治三年，决志抛资产，先设飞脚船，便内国之运输；次谋创铁道；次建设洋学校，聘教师于外国，以振起教育之业；布设瓦斯灯于横滨港内，至七年之冬，得成此四大创始工业。此四大工业，当时邦人，实未尝着手，余为之创始也。明治七年，瓦斯灯建成之日，荣邀天皇陛下临幸，蒙赐接见。余当时怀藏先考灵牌，冀得同《观》天颜，又荷宠颁进步首倡敕语。拜受之下，荣何如之！此卦以第五爻为《同人》之主，以年计之，初爻至五爻，恰是五年。今自明治三年，至七年，其间九三之伏莽，九四之乘塘，多有障碍余事业者，然余公平无私，百折不屈，果得奏效。然物盛必衰，势极必变，是天理之常，余虽乘《同人》之运，得成厥事，若味人事穷通之理，知进而不知退，恐有“亢龙”之悔，即《同人》上九诫之曰“同人于郊，无悔”。是《易》理之妙用也，其旨深矣。迨八年，余居神奈川郊外望欣台，优游逍遥，间玩《易》理，以至今日。爰述《同人》之卦义，追怀往事，附记数语。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“戎”者，兵戎也。“莽”者，草深处也。此卦六二，一阴居中，卦中诸阳，皆欲与同。三爻接二最近，欲同之意尤切，然二爻中正，为九五正应，不与三同。三爻过刚不中，性情刚暴，位居二五之间，欲用强而同之。然惧二之中正，畏五之刚健，不敢显发，“伏戎于莽”，以俟其机，上升高陵，以窥其隙，至三岁之久，终不敢兴，亦可见小人之情状矣。其不言凶者，以久而不兴，故未至凶矣，然曰“伏”，曰“升”，其凶已露矣。《象传》曰“敌刚”也者，谓其所敌九五刚健，自知不能胜也；“安行”也者，“三岁不兴”，亦安行乎？《离》为甲，兵戎之象，互卦《巽》，为隐伏之象。此卦九三九四，不言同人者，两爻共有争夺之象，非同人者也。此爻变为《无妄》，其六三之辞曰：“无妄之灾，或系之牛，行人之得，邑人之灾”。可以见其有凶咎也。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：目下直潜伏，三岁后方可出而谋事。</p><p>○　问商业：宜开山林，三年后大可获利。</p><p>○　问家宅：防有盗贼窃伺。</p><p>○　问战征：须防敌军埋伏。</p><p>○　问讼事：虑有意外葛藤，一时不了。</p><p>○　问失物：须于丛草中寻之，或山上草中。</p><p>○　问行人：俟三年后可归。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>明治二十四年，某贵显来请占当年气运，筮得《同人》之《无妄》。</p><p>断曰：此卦有公同谋事之象，故曰《同人》。在世间智者少而愚者多，古今皆然。今人往往采取朝野大众之论说，谓之公议，所云谋野则获者是也，故《彖》曰“同人于野，亨”。及三爻刚而不中，强欲求同，不曰“于野”，而曰伏莽，又自知畏惧，终久而不敢兴。其象如是，气运可知，请俟三年后而谋之可也。后果如此占。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>“墉”者，城垣也。此爻以刚居柔，而不中正，四与二非应，亦非比，而欲强同于二，且中间隔以九三之“墉”并忌二五粮密，故欲“乘其猜”而攻焉。既思九五刚健中正，攻之于义不直，于势亦不敌，必弗能克，故不攻也。即此转念间，悔过而改善，乃得变凶而为吉，谓之“乘其墉，弗克攻，吉”《象传》曰“义弗克也”者，谓不自逞其强，而能反省夫义，是以吉也。“困而反则也”者，谓不义之举，必陷困厄，止其邪念，而所法则也。此卦名《同人》，三四两爻，均有乖象。人情同极则必异，异极则复同，犹国家之治极而乱，乱极复治也。是人事分合之端，即《易》道循环之理也。凡《易》曰不克，皆以阳居阴之爻，惟其阳，故有《讼》，有攻；惟其阴，故弗克也。此爻及《讼》之九二九四，如“不克讼”，皆是也。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：目下直退守弗动，吉。</p><p>○　问商业：宜垄断货物，待价弗售，后必获利。</p><p>○　问家宅：宜修葺墙垣，吉。</p><p>○　问战征：直坚筑营磊，防敌袭击。</p><p>○　问讼事：今虽不直，后反得胜。</p><p>○　问失物：久后可得。</p><p>○　问疾病：虽凶无害。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>友人来告白：今有一业可兴，请占其成败。筮得《同人》之《家人》。</p><p>断曰：此卦有合众兴事之象，其事必关公共利益可知也。九五《乾》之有金力者，与六二《离》之聪明者，阴阳相应而成事，其间有九三九四两爻，嫉妒其利益，于中阻挠，以谋占取之象。足下为占事业，以爻辞观之，知足下或羡彼之事业，谋彼之权利，将夺取而代之乎？足下一时不露声色，惟阴使同意者九三，为之计划，即爻辞所云乘墉，如乘垣而伺敌，潜伏而谋事之谓也。然此事必难遂志，不如中止，谓之“弗克攻，吉”，故《象传》曰“困而反则也”。后有所闻，果如此占。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>“号咷”者，谓悲忧之甚而啼哭也。此爻君位，当与天下同应，若独与二亲密，非人君之道，即非大同之道也。是以为九三九四所嫉妒，隔绝阻挠，使不得与六二相遇，遂致兴师攻克，始得相遇，盖其初以不遇而号咷，今得相遇而笑乐，谓之“同人，先号咷而后笑，大师克相遇”。在五与二，刚柔相应，上下相洽，其情似私，其理本正，故《象传》明其“中直”，《彖传》称其“中正”，是师壮而得克也，岂得以私匿病之哉！又一说：长国家而欲和同众人，其间有猜疑而离间者，使之隔绝而不相遇，极之号咷悲泣，使离间者亦服其德，复得和同而笑乐也。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：目下正当欢乐之时，从前苦志，今得遂愿。</p><p>○　问商业：虽小有挫折，终获大利。</p><p>○　问家宅：防有惊惶之虑，然终得平和也。</p><p>○　问疾病：先危后安。</p><p>○　问讼事：须请大好辩护士，方能得直。</p><p>○　问行人：防中途有阻，须缓得归。</p><p>○　问六甲：生男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十五年三月，余漫游骏州兴津，阅新闻纸，知北海道炭矿欣道会社堀基氏免职。余为是社评议员，遂速归京，与同事涩泽荣一、汤地定基、田中平八等，共为会社周旋，方得协议，评议委员定以汤地与余两名中，充任社长，请愿于该官厅。同事诸君，预问余之诺否，余先取决于筮，筮得《同人》之《离》。</p><p>断曰：此卦六二一阴得时，又得中正之地位，上下五阳应之，余之就任社长也。九五之政府，九三之北海道厅长官，九四之大臣，初九之社员，上九远方之株主，不特不倡异议，定必同心喜悦可知也，谓之“同人，柔得位得中而应乎《乾》，曰《同人》”至处之之道，如平原广野，无所隐蔽，一以光明正大为主也，谓之“于野，亨”。余虽不才，于此等事业，久经历验，加之以六百五十万元之金力，与政府补给之利子，余惟公明正大，毫无私曲，可得胜此责任，谓之“文明以健，中正而应，君子正也”。此会社在人迹稀绝之区，凡执工业者，多非常劳动，亦不免暗生情弊，此亦势所必有也。一旦革绝其弊，必生诽谤，然既任其事，自当任怨任劳。谚曰一功能服，百论得快，政理则疑谤自灭，谓之“君子为能通天下之志”。即有如九三九四，以不得兴事，生出意外枝节，百计窥伺，相谋窃夺，余当预定目的，终不受其害也，谓之“同人先号咷而后笑，大师克相遇”也。余得此占，承诺社长之任，后果如此占。在任五百四十日间，会社之整理，幸博同人之信用，价格四十四圆之株卷，腾贵至八十四元，其十三万株，合计五百二十万元，足见会社之盛运也。以在任之日数除之，平均一日，大凡一万元，是可谓全以道德得之者也。呜呼！谁谓为仁不富乎？谓道德与经济相反者，此乃愚而无知者之言也。夫道德之功效，优于区区之经济，不知其几千百倍也。世之好夸大，言内无实学者，宜知所猛省矣！</p><p>明治二十八年四月，我国与清国讲和约成，将遣大使于清国芝罘，交换条约。时法、德、俄三国，联合告我以不可久占辽东，且聚战舰于芝罘，有动辄起事之势，上下心颇不安。各大臣及机密顾问官等，皆赶西京，余亦闻之至西京，会土方宫内大臣、杜边大藏大臣于木屋町柏亭。两大臣谓曰：今日之势，三国联合迫我，其意有不可测者。我军舰劳数月之海战，且有许多损伤，不复适战斗之用，实危急存亡之秋也。占筮决疑，其在此时乎？余曰：曾已占之，筮得《同人》之《离》，请陈其义。</p><p>《同人》一卦，二爻一阴得中正，在五阳之间，辉离明于宇内之象。卦德有文明与刚健，通志于天下时也。今得五爻，则知大事必遂也。法、德、俄三国，联合妨我行为，且欲逞溪壑之愿，聚合军舰于芝罘，又在各要港，悉整戎备，有不愆时期而举事之意，又有夺我所得清国偿金之胸算，其狡计炳如见火。就爻象推究，其中妨阻二五之交者，三四两爻，三爻之辞不云乎？”伏戎于莽，升其高陵，三岁不兴。”“伏戎于莽”者，谓自航海之要路，突然袭击之备；“升其高陵”者，谓从旁窥伺其隙也；“三岁不兴”者，谓等机而动，不遽发也。四爻之辞不云乎？“乘其墉，义弗克也；其吉，则困而反则也。”四与三同意，欲乘隙而起者也，谓之“乘其塘”；然以义有不直，故曰“义不克也”。是亦不能举事而止，故曰“其吉，则困而反则也”。三国之非望如此，天命不许，不足介意也。今得五爻之占，虽忧三国之障，然必得清帝批准条约，喜可知也，谓之“同人，先号咷而后笑”。日后不为宇内各国所轻侮，终得战胜之誉，宜扬国光于万里，谓之“大师克相遇”。占筮如此，我元老何须忧虑？于是两大臣扬眉，不堪欣喜。后果庙议一如此占，直以商船遣伊东已代治氏于芝罘，交换条约而归。当时三国虽伺我衅隙，无举事之辞，非常之备，无所复用，如《易》辞所示也。</p><p>明治二十九年一月，余避寒于热海，偶得神奈川县吉田书记官报曰：前农商务大臣白根专一君罹大患，入大学病院，内外名医，无所施治，束手待死而已。吾得君之知遇久矣，不堪忧苦，希其万死一生，敢烦一筮。筮得《同人》之《离》。</p><p>断曰：白根君疾，一时国医束手，谓症必不治，待死而已。据此占，料君不特不死，且即日愈快，谓之“同人，先号咷而后笑”；其病或必得大汗大泻而愈，故曰“大师克相遇”。但此卦上爻为归魂，今得五爻，则上爻正当明年，明年恐或难保。然上爻之辞曰，“同人于郊，无悔”，此番愈快之后，宜移从近郊闲散之地，远于世累，休息静养，尽我人事，亦足挽回天命，或得无悔。乃记以报之。后果大患徐徐而愈。德人白耳都氏以下诸名医，不知其快复之理，后余亦访君于病院，面渠夫人，劝以出院之后，宜就闲地休息静养。然君以得复健康，不复应余之劝，翌年果复得疾不治，不堪痛惜。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>“郊”者，国都之外，旷远之地。此爻在五爻之上，为无位之地。《同人》一卦，卦中五阳皆欲同于六二一阴，三爻与二相比，其欲同之意尤切。四爻非应非比，然以介在二五之间，亦欲强同于六二。五爻与二为正应，惟此爻居上，与二非应非比，孤介特立，置身荒郊之外，较初之于门更远。无私匿之情，免争夺之患，在六爻中，最为完善，谓之“同人于郊，无悔”。盖《同人》之量，“愈远则愈大，国外曰郊，郊外曰野，“于郊”较野殊近，故“于野”则亨，于郊”则第曰“无悔”。《象传》曰“志未得也”，志即“为能通天下之志”而言，其仅曰“于郊”。犹未能通天下之志也，故曰“志未得也”。</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问时运：目下顺适，诸事无所障碍，但宜在闲散之地。</p><p>○　问商业：宜立业于市尘之外，无忧耗损，一时亦未能获大利益。</p><p>○　问战征：宜在荒地屯营。</p><p>○　问失物：于郊外觅之。</p><p>○　问讼事：恐难得直。</p><p>○　问家宅：平顺无灾。此卦为归魂之卦，若占命数而得此卦，至上爻必死。《师》之上爻，可参看也。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>有相识会社役员某氏来，告曰：近来我会社头取，与大株主之间，颇生纷议。株主欲开总会，改选社员，又有一派赞成当时之社员者，竞争颇甚。余不自知免职与否，请占前途之气运。筮得《同人》之《革》。</p><p>断曰：《同人》者，与人相同也。勿论社员株主，皆思其社之利益，非各谋私利者，惟其所为有左有之差，而遂生纷议也。盖此纷议之来，由五爻之头取，与二爻之支配人，其间过相亲密，致启他人之疑，然其疑可不久解也。如足下不偏不党，无所关系，亦无免职之忧，故曰“于郊，无悔”。郊者，田舍之谓，而离市街烦杂之地也。后果如此占。</p>',102)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
